      "raw_content": "카페홈\n좌담회/설문/주부알바\n가입\n검색\n메뉴\n▶좌담회 신청하기(당일 현금지급)\n앱 열기\n▶11/17~18)스트리밍 서비스 온라인 줌 좌담회 / 만19세~64세 남녀\n본문 기타 기능\n하늘\n카페매니저\n채팅\n작성일\n2026.10.30. 19:24\n조회 37\n▶11/17~18)스트리밍 서비스 온라인 줌 좌담회 / 만19세~64세 남녀\n=====================================\n<대상 조건>\n1. TV,영화,뉴스등을 주 몇회씩 자주 시청하시는 분\n2. OTT 서비스 이용하며 본인이 결제하시는분\n3. OTT 서비스 이용하며 타인이 결제하는 계정을 공유 받으시는분\n4. 학사 학위 이상 (대학교 재학생 불가, 졸업만 가능)\n5. 온라인 줌 진행 -> 카메라 내장 노트북, 웹캠 및 마이크 있는 PC보유자만 참여 가능 (스마트폰, 태블릿 참여 불가)\n-------------------------------------------------------------------\n<좌담회 일정>\n- 방식: 온라인 줌 좌담회\n- 일시: 17~18일중 1회 참여 (20분 전까지 줌링크 접속하여 카메라 및 마이크 테스트 필수, 그때 접속 불가능하신분들은 신청 말아주세요)\n1) 11월 17일 (화) 오후 7시\n2) 11월 17일 (화) 오후 9시\n3) 11월 18일 (수) 오후 7시\n- 소요시간: 90분 내외\n-------------------------------------------------------------------\n<사례비> 5만원\n# 카페같은곳에서 진행하는것 불가합니다. 혼자 있을 수 있는 조용한 회의실이나 집에서 접속 가능하신분만 신청 부탁 드립니다.\n-------------------------------------------------------------------\n==>소개자란 [김현숙]을 반드시 입력해야 신청완료 됩니다.\n(간혹 소개자란에 본인 이름, 지인 이름, 없음, 네이버 카페... 이런식으로 적으면 접수 안 됩니다.)\n[아래 URL에 (클릭!!)하여 설문 진행해주세요.(스마트폰도 가능)\nhttps://survey-insight.com/?ACCESS_KEY=3cf1fd73-a967-4d90-a9d9-f14120ddc0fa&UID=\n좋아요\n0\n논현동에서 많이 본 동네소식 보러가기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n지금 가입하고 댓글에 참여해보세요!\n전체글\n▶ 11/16~20일 ]자동차 통합관리 관련 (인터뷰) / 남녀\n하늘\n26.10.30.\n댓글\n0\n▶11/17~18)스트리밍 서비스 온라인 줌 좌담회 / 만19세~64세 남녀\n하늘\n26.10.30.\n댓글\n0\n▶11/11 ] 단백질 음료 취식자 맛테스트 /만 20세~39세 남여\n하늘\n26.10.30.\n댓글\n0\n▶11/12~13 ] 홈리빙(이사/청소/인테리어/설치/수리) 서비스 관련 좌담회/만 35~44세 남녀\n하늘\n26.10.30.\n댓글\n0\n좌담회/설문/주부알바\n 카페에 가입해 보세요!\n가입하면 1.1만개의 글을 볼 수 있어요\n10초 만에 가입하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
