      "type": "좌담회",
      "raw_content": "카페홈\n좌담회/설문/주부알바\n가입\n검색\n메뉴\n▶좌담회 신청하기(당일 현금지급)\n앱 열기\n▶11/21.22 ]중 고등학생_모바일 게임을 주로 하는 중고생[pc보다 모바일을 주로 하는 학생]\n본문 기타 기능\n하늘\n카페매니저\n채팅\n작성일\n2026.10.30. 21:52\n조회 6\n▶11/21.22 ]중 고등학생_모바일 게임을 주로 하는 중고생[pc보다 모바일을 주로 하는 학생]\n=============================\n◈조사 조건\n*현재 중학교 /고등학교 재학(1학년~3학년) 중인 남학생,여학생 모두 가능\n*최근 1개월이내 모바일로 게임을 하는 학생\n*6개월이내 PC 게임- 안 하는 학생\n**좌담회 시작전 게임에 관련된 과제물 작성후(일부) 좌담회 참석\n-------------------------------------------------------------------\n◈진행 날짜/시간_주말 11월 21일(토요일)/11월22일(일요일)_11시/3시/7시\n◈하루1타임 2시간내외====>사 례 비(당일지급) :참석비_7만원/ 과제물작성완료시_3만원 추가 지급\n◈위 치 : 충정로역(전화 인터뷰후 참석 확정되신 분에 한하여 문자로 알려드립니다)\n-------------------------------------------------------------------\n▶기재 사항\n-이름/연락처/성별/생년월일/만나이/거주지역(동까지)/학교명,학년\n-주이용게임기기/최근 1개월이내 플레이한 게임_모두 적어주세요/주게임횟수/주게임시간/최근 3개월이내 TFT전략적게임플레이 경험여부_있으면 게임명 기입,없으면 없다\n예시)모바일/로블록스,로얄매치,오토베틀러/주 6일/주12시간/TFT한다_오토베틀러\n-이메일주소\n-원하는 날짜,시간\n-------------------------------------------------------------------\n==>소개자 [김현숙]\n[아래 URL에 (클릭!!)하여 설문 진행해주세요.(스마트폰도 가능)\nhttps://forms.gle/xd5rGeDDrXW8rnb8A\n좋아요\n0\n논현동에서 많이 본 동네소식 보러가기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n지금 가입하고 댓글에 참여해보세요!\n전체글\n▶11/10 ]최근1년내 식기세척기 구입자 좌담회 / 만25-59세 남여\n하늘\n26.10.30.\n댓글\n0\n▶11/21.22 ]중 고등학생_모바일 게임을 주로 하는 중고생[pc보다 모바일을 주로 하는 학생]\n하늘\n26.10.30.\n댓글\n0\n▶추후협의)미스테리 조사/ 만20-59세 남녀\n하늘\n26.10.30.\n댓글\n0\n▶추후협의 ]금융모니터링 / 전국 성인남여\n하늘\n26.10.30.\n댓글\n0\n좌담회/설문/주부알바\n 카페에 가입해 보세요!\n가입하면 1.1만개의 글을 볼 수 있어요\n10초 만에 가입하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
