      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n20~50대 남성 )미스테리 조사\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.30. 12:03\n조회 202\n구독\n20~50대 남녀)미스테리 조사\n관련해서 해당되신분께 자세히 안내드립니다\n* 미스터리조사란 : 조사원이 고객 신분으로 가장하고 직원들의 상담 내용을 평가\n1. 대상자 조건\n- 20~50대 남녀\n- 최근 1년 이내 신용카드 발급 이력이 없는 분\n- 대면으로 직원을 만나 신용카드 발급이 가능한 분\n2. 조사 진행 방식\n직원을 직접 만나 신용카드를 발급 신청하고, 실물 카드 수령까지의 전체 발급 과정을 확인한 후 평가표를 작성합니다.\n직원과 대면하여 신용카드를 발급받는 과정은 반드시 녹취해야 합니다.\n녹취가 진행되지 않거나 녹취 파일을 제출하지 못한 경우 사례비 지급이 불가합니다.\n3. 조사 사례비\n사례비: 100,000원 (카드 연회비 포함)\n- 조사 진행비 9만원 + 교육비 1만원(1시간 정도 소요)\n- 카드 발급 취소는 선택사항이며, 취소하지 않고 계속 사용하셔도 됩니다.\n- 단, 카드 발급을 취소하실 경우에는 조사 완료(평가표 작성까지 모두 완료) 후 약 일주일이 지난 시점에 취소해 주시면 됩니다.\n** 신청양식 :\n이름 / 연락처 / 성별 / 연령 / 회사명 / 업종 / 미스터리조사 경험 있는지 / 있다면 어떤 조사 참여해 봤는지 / 최근 1년 이내에 신용카드 발급 이력 유무 / 대면으로 만나서 신용카드 발급 가능한지 / 현재 사용하고 있는 신용카드 / 최근 3개월내 이용한 대형마트 / 개인 정보 동의 여부\nhttps://forms.gle/iSqKdyU7ttxwPPnA9\n좋아요\n2\n좋아요한 사람 목록으로 이동\n송파구에서 핫한 진짜 동네 이야기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.10.30. 17:59 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n20~50대 여성 )미스테리 조사\n좌담회알바좌담회카페\n26.10.30.\n댓글\n1\n20~50대 남성 )미스테리 조사\n좌담회알바좌담회카페\n26.10.30.\n댓글\n1\n26~59세 남여 )정수기 이용자 및 구매담당자 워크샵\n좌담회알바좌담회카페\n26.10.30.\n댓글\n1\n전국 성인여성) 금융모니터링\n좌담회알바좌담회카페\n26.10.30.\n댓글\n1\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n2\n좋아요한 사람 목록으로 이동\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
