      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n11월 17일(화) ~ 18(수) 만나이 19세~64세 여성) 온라인 줌 좌담회\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.30. 16:28\n조회 285\n구독\n11월 17일(화) ~ 18(수) 만나이 19세~64세 남녀) 온라인 줌 좌담회\n<대상 조건>\n1. TV,영화,뉴스등을 주 몇회씩 자주 시청하시는 분\n2. OTT 서비스 이용하며 본인이 결제하시는분\n3. OTT 서비스 이용하며 타인이 결제하는 계정을 공유 받으시는분\n4. 2026년 기준 만나이 19세~64세 남녀\n5. 학사 학위 이상 (대학교 재학생 불가, 졸업만 가능)\n6. 온라인 줌 진행 -> 카메라 내장 노트북, 웹캠 및 마이크 있는 PC보유자만 참여 가능 (스마트폰, 태블릿 참여 불가)\n<좌담회 일정>\n- 방식: 온라인 줌 좌담회\n- 일시: 17~18일중 1회 참여 (20분 전까지 줌링크 접속하여 카메라 및 마이크 테스트 필수, 그때 접속 불가능하신분들은 신청 말아주세요)\n1) 11월 17일 (화) 오후 7시\n2) 11월 17일 (화) 오후 9시\n3) 11월 18일 (수) 오후 7시\n- 소요시간: 90분 내외\n<사례비>\n5만원\n<신청 방법>\n아래 URL에 접속하여 사전 설문 응답 진행해주세요. (스마트폰에서도 응답 가능)\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\nhttps://survey-insight.com/?ACCESS_KEY=3cf1fd73-a967-4d90-a9d9-f14120ddc0fa&UID=\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\n# 카페같은곳에서 진행하는것 불가합니다. 혼자 있을 수 있는 조용한 회의실이나 집에서 접속 가능하신분만 신청 부탁 드립니다.\n# 설문 종료 후 조건에 맞는 분께 개별적으로 연락 드릴 예정이며, 조건이 맞지 않거나 신청이 많아 조기 마감될 경우 전화가 가지 않을 수도 있습니다.\n# 설문응답 마지막 개인정보 입력 시 소개자 이름은 필수로 입력하셔야 합니다.\n좋아요\n3\n좋아요한 사람 목록으로 이동\n송파구의 더 많은 인기글 보러가기\n댓글\n2\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.10.30. 17:57 답글쓰기\n옵션\n좋아요\n최블루\n신입회원\nNew\n사이트가 열리지 않습니다!\n2026.10.30. 18:50 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n11/16~20)  20~59세 남성) 자동차 통합관리 관련 인터뷰(조사)\n좌담회알바좌담회카페\n26.10.30.\n댓글\n1\n11월 17일(화) ~ 18(수) 만나이 19세~64세 여성) 온라인 줌 좌담회\n좌담회알바좌담회카페\n26.10.30.\n댓글\n2\n11월 17일(화) ~ 18(수) 만나이 19세~64세 남성) 온라인 줌 좌담회\n좌담회알바좌담회카페\n26.10.30.\n댓글\n1\n11월~12월 약 2달)단기 아르바이트\n좌담회알바좌담회카페\n26.10.30.\n댓글\n1\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n3\n좋아요한 사람 목록으로 이동\n댓글\n2\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
